package net.civeira.phylax.feature.observe.observedslo.domain;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

class ObservedSloChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_slo_change_set_builder() {
    ObservedSloChangeSet one =
        new ObservedSloChangeSet().uid("one").name("one").origin(ObservedSourceReference.of("one"))
            .route("one").kind(ObservedSloKindOptions.AVAILABILITY).objective(1).latencyMs(1)
            .windowDays(1).enabled(true).version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getName().get(), "Value must equals to the intial value");
    one.name("two");
    Assertions.assertEquals("two", one.getName().get(), "Value must equals to the assigned value");
    one.unset("name");
    Assertions.assertFalse(one.getName().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedSourceReference.of("one"), one.getOrigin().get(),
        "Value must equals to the intial value");
    one.origin(ObservedSourceReference.of("two"));
    Assertions.assertEquals(ObservedSourceReference.of("two"), one.getOrigin().get(),
        "Value must equals to the assigned value");
    one.unset("origin");
    Assertions.assertFalse(one.getOrigin().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getRoute().get(), "Value must equals to the intial value");
    one.route("two");
    Assertions.assertEquals("two", one.getRoute().get(), "Value must equals to the assigned value");
    one.unset("route");
    Assertions.assertFalse(one.getRoute().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedSloKindOptions.AVAILABILITY, one.getKind().get(),
        "Value must equals to the intial value");
    one.kind(ObservedSloKindOptions.LATENCY);
    Assertions.assertEquals(ObservedSloKindOptions.LATENCY, one.getKind().get(),
        "Value must equals to the assigned value");
    one.unset("kind");
    Assertions.assertFalse(one.getKind().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getObjective().get(), "Value must equals to the intial value");
    one.objective(2);
    Assertions.assertEquals(2, one.getObjective().get(), "Value must equals to the assigned value");
    one.unset("objective");
    Assertions.assertFalse(one.getObjective().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getLatencyMs().get(), "Value must equals to the intial value");
    one.latencyMs(2);
    Assertions.assertEquals(2, one.getLatencyMs().get(), "Value must equals to the assigned value");
    one.unset("latencyMs");
    Assertions.assertFalse(one.getLatencyMs().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getWindowDays().get(), "Value must equals to the intial value");
    one.windowDays(2);
    Assertions.assertEquals(2, one.getWindowDays().get(),
        "Value must equals to the assigned value");
    one.unset("windowDays");
    Assertions.assertFalse(one.getWindowDays().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(true, one.getEnabled().get(), "Value must equals to the intial value");
    one.enabled(false);
    Assertions.assertEquals(false, one.getEnabled().get(),
        "Value must equals to the assigned value");
    one.unset("enabled");
    Assertions.assertFalse(one.getEnabled().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
